import { useMemo, useSyncExternalStore } from 'react'
import { statusOf } from '../../data/card_ordering'
import { defaultColumnAccent, type StateConfig } from '../../data/data_types'
import {
    CARD_ADDED_EVENT,
    CARD_REMOVED_EVENT,
    cardCollectionFieldChangedEvent,
    dataService,
    type CardAddedEventDetail,
    type CardRemovedEventDetail,
    type DataService,
} from '../../services/data/data_service'

export interface VisibleCardColumn {
    color: string
    status: string
}

function areSameColumns(first: VisibleCardColumn[], second: VisibleCardColumn[]) {
    return first.length === second.length && second.every((column, index) => (
        first[index].color === column.color && first[index].status === column.status
    ))
}

class CardViewColumnStore {
    private columns: VisibleCardColumn[]
    private listener: (() => void) | null = null
    private readonly service: DataService
    private readonly states: StateConfig[]
    private readonly statusCounts: Map<string, number>

    constructor(states: StateConfig[], service: DataService) {
        this.service = service
        this.states = states
        this.statusCounts = new Map()
        const cards = service.getState().snapshot?.activeCards ?? []
        for (const card of cards) this.incrementStatus(statusOf(card))
        this.columns = this.visibleColumns()
    }

    readonly getSnapshot = () => this.columns

    readonly subscribe = (listener: () => void) => {
        this.listener = listener
        this.service.addEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
        this.service.addEventListener(cardCollectionFieldChangedEvent('status'), this.handleCardStatusesChanged)
        this.service.addEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)

        return () => {
            this.listener = null
            this.service.removeEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
            this.service.removeEventListener(cardCollectionFieldChangedEvent('status'), this.handleCardStatusesChanged)
            this.service.removeEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)
        }
    }

    private readonly handleCardAdded = (event: Event) => {
        const { card } = (event as CustomEvent<CardAddedEventDetail>).detail
        this.incrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private readonly handleCardStatusesChanged = () => {
        this.statusCounts.clear()
        const cards = this.service.getState().snapshot?.activeCards ?? []
        for (const card of cards) this.incrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private readonly handleCardRemoved = (event: Event) => {
        const { card } = (event as CustomEvent<CardRemovedEventDetail>).detail
        this.decrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private incrementStatus(status: string) {
        this.statusCounts.set(status, (this.statusCounts.get(status) ?? 0) + 1)
    }

    private decrementStatus(status: string) {
        const nextCount = (this.statusCounts.get(status) ?? 0) - 1
        if (nextCount > 0) {
            this.statusCounts.set(status, nextCount)
        } else {
            this.statusCounts.delete(status)
        }
    }

    private publishVisibleColumns() {
        const nextColumns = this.visibleColumns()
        if (areSameColumns(this.columns, nextColumns)) return

        this.columns = nextColumns
        this.listener?.()
    }

    private visibleColumns() {
        return this.states
            .map(({ alwaysVisible, color, state }, index) => ({
                alwaysVisible,
                color: color ?? defaultColumnAccent(index),
                status: state,
            }))
            .filter(({ alwaysVisible, status }) => alwaysVisible || this.statusCounts.has(status))
            .map(({ color, status }) => ({ color, status }))
    }
}

/** Subscribes only to changes in which configured board columns must be visible. */
export function useCardViewColumns(states: StateConfig[], service: DataService = dataService) {
    const store = useMemo(() => new CardViewColumnStore(states, service), [service, states])

    return useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
}

import { useCallback, useRef, useSyncExternalStore } from 'react'
import { orderByAfter, UNASSIGNED_STATUS } from '../../data/card_ordering'
import {
    CARD_ADDED_EVENT,
    CARD_REMOVED_EVENT,
    cardCollectionFieldChangedEvent,
    dataService,
    type CardAddedEventDetail,
    type CardRemovedEventDetail,
    type DataService,
} from '../../services/data/data_service'

function cardStatus(event: Event) {
    return (event as CustomEvent<CardAddedEventDetail | CardRemovedEventDetail>).detail.card.header.status
        ?? UNASSIGNED_STATUS
}

function areSamePaths(first: string[], second: string[]) {
    return first.length === second.length && second.every((path, index) => first[index] === path)
}

/** Subscribes to ordered membership changes for one board column, not card data edits. */
export function useCardColumnCards(status: string, service: DataService = dataService) {
    const pathsRef = useRef<string[]>([])
    const subscribe = useCallback((onStoreChange: () => void) => {
        const handleCardAddedOrRemoved = (event: Event) => {
            if (cardStatus(event) === status) {
                onStoreChange()
            }
        }
        service.addEventListener(CARD_ADDED_EVENT, handleCardAddedOrRemoved)
        service.addEventListener(cardCollectionFieldChangedEvent('ordering'), onStoreChange)
        service.addEventListener(CARD_REMOVED_EVENT, handleCardAddedOrRemoved)

        return () => {
            service.removeEventListener(CARD_ADDED_EVENT, handleCardAddedOrRemoved)
            service.removeEventListener(cardCollectionFieldChangedEvent('ordering'), onStoreChange)
            service.removeEventListener(CARD_REMOVED_EVENT, handleCardAddedOrRemoved)
        }
    }, [service, status])
    const getSnapshot = useCallback(() => {
        const cards = service.getState().snapshot?.activeCards ?? []
        const nextPaths = orderByAfter(cards.filter((card) => (
            (card.header.status ?? UNASSIGNED_STATUS) === status
        ))).map((card) => card.path)
        if (areSamePaths(pathsRef.current, nextPaths)) return pathsRef.current

        pathsRef.current = nextPaths

        return nextPaths
    }, [service, status])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import { Box, IconButton, Menu, MenuItem, Stack, TextField, Tooltip, Typography, useTheme } from '@mui/material'
import { alpha } from '@mui/material/styles'
import DotsVertical from 'mdi-material-ui/DotsVertical'
import FileDocumentOutline from 'mdi-material-ui/FileDocumentOutline'
import { memo, useCallback, useMemo, useState, useSyncExternalStore } from 'react'
import type { ChangeEvent, KeyboardEvent, MouseEvent } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { cardContext } from '../../data/action_context'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { dialogService } from '../../services/dialog_service'
import { ActionEntryPoints } from '../actions/run/trigger/action_entry_points'
import { CardRunButton } from '../actions/run/trigger/card_run_button'
import { useRunningActionForContext } from '../hooks/use_action_runs'
import { CardDeleteDialog } from './card_delete_dialog'
import { CardPathMenuItems } from './card_path_menu_items'
import { CardPolicyMenuItem } from './card_policy_menu_item'
import { CardWorktreeIndicator } from './card_worktree_indicator'
import { getCardTypeColor } from './card_drag'
import { useCardMetadata, type CardMetadataSnapshot } from './use_project_card'
import { useProjectReference } from '../hooks/use_project_reference'
import { useIsWorkspacePathSelected } from '../hooks/use_is_workspace_path_selected'
import { cardBodyPopoverService, subscribeCardBodyPopover } from './card_body_popover_service'
import { CardDragContainer } from './project_card_drag_container'

export interface CardHandlers {
    onDeleteCard: (path: string) => Promise<void>
    onOpenInFileMode: (path: string) => void
    onTogglePolicy: (path: string, policyKey: string) => void
    onTitleChange: (path: string, title: string) => void
}

interface CardViewProps extends CardHandlers {
    cardPath: string
    cardTypes: CardTypeConfig[]
    isMobile: boolean
}

interface CardViewContentProps extends CardHandlers {
    card: CardMetadataSnapshot
    cardTypes: CardTypeConfig[]
    isSelected: boolean
    isMobile: boolean
    primaryPath: string
    rootPath: string | undefined
}

interface MenuPosition {
    left: number
    top: number
}

/** A three-row draggable card with compact metadata and consolidated actions. */
export const CardView = memo(function CardView(props: CardViewProps) {
    const { cardPath, ...contentProps } = props
    const card = useCardMetadata(cardPath)
    const project = useProjectReference()
    const isSelected = useIsWorkspacePathSelected(cardPath)
    if (!card || !project) return null

    const primaryPath = project.rootPath ?? project.id
    return (
        <CardViewContent
            card={card}
            isSelected={isSelected}
            primaryPath={primaryPath}
            rootPath={project.rootPath}
            {...contentProps}
        />
    )
})

function CardViewContent(props: CardViewContentProps) {
    const { card, cardTypes, isSelected, primaryPath, rootPath } = props
    const { onOpenInFileMode } = props
    const { onDeleteCard, onTogglePolicy, onTitleChange } = props
    const theme = useTheme()
    const [cardElement, setCardElement] = useState<HTMLDivElement | null>(null)
    const [actionsAnchorElement, setActionsAnchorElement] = useState<HTMLElement | null>(null)
    const [actionsMenuPosition, setActionsMenuPosition] = useState<MenuPosition | null>(null)
    const [isEditingTitle, setIsEditingTitle] = useState(false)
    const [deleteCardPath, setDeleteCardPath] = useState<string | null>(null)
    const [titleDraft, setTitleDraft] = useState(card.header.title)
    const isBodyOpen = useSyncExternalStore(
        subscribeCardBodyPopover,
        () => cardBodyPopoverService.getSnapshot().cardPath === card.path,
        () => false,
    )
    const accentColor = getCardTypeColor(cardTypes, card.header.id) ?? theme.palette.primary.main
    const accentBackground = alpha(accentColor, 0.16)
    const context = cardContext(card, cardTypes)
    const runningRun = useRunningActionForContext(context)
    const statusLabel = runningRun ? 'Running' : 'Idle'

    const commitTitle = () => {
        setIsEditingTitle(false)
        const nextTitle = titleDraft.trim()
        if (nextTitle.length > 0 && nextTitle !== card.header.title) onTitleChange(card.path, nextTitle)
    }

    const handleTitleKeyDown = (event: KeyboardEvent) => {
        if (event.key === 'Enter') commitTitle()
        if (event.key === 'Escape') setIsEditingTitle(false)
    }

    const handleTitleDraftChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitleDraft(event.target.value)
    }

    const handleCardClick = useCallback((event: MouseEvent<HTMLElement>) => {
        if (isEditingTitle) return

        cardBodyPopoverService.toggle(card.path, event.currentTarget)
        telemetryService.trackEvent('navigation')
    }, [card.path, isEditingTitle])

    const stopClick = (event: MouseEvent) => {
        event.stopPropagation()
    }

    const openCardActions = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        setActionsMenuPosition(null)
        setActionsAnchorElement(event.currentTarget)
    }

    const openCardContextMenu = useCallback((event: MouseEvent<HTMLElement>) => {
        event.preventDefault()
        event.stopPropagation()
        if (props.isMobile) return

        setActionsAnchorElement(null)
        setActionsMenuPosition({ left: event.clientX, top: event.clientY })
    }, [props.isMobile])

    const openInFileMode = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        onOpenInFileMode(card.path)
    }

    const closeCardActions = () => {
        setActionsAnchorElement(null)
        setActionsMenuPosition(null)
    }

    const openBodyFromMenu = () => {
        try {
            if (!cardElement) throw new Error(`Missing card element: ${card.path}`)
            closeCardActions()
            cardBodyPopoverService.toggle(card.path, cardElement)
            telemetryService.trackEvent('navigation')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card details could not be opened' })
        }
    }

    const openInFileModeFromMenu = () => {
        closeCardActions()
        onOpenInFileMode(card.path)
    }

    const editTitleFromMenu = () => {
        closeCardActions()
        setTitleDraft(card.header.title)
        setIsEditingTitle(true)
    }

    const closeDeleteCardDialog = () => {
        setDeleteCardPath(null)
    }

    const openDeleteCardDialog = () => {
        closeCardActions()
        setDeleteCardPath(card.path)
    }

    const policyKeys = Object.keys(card.header.policy)
    const dragInteractions = useMemo(() => ({
        onClick: handleCardClick,
        onContextMenu: openCardContextMenu,
    }), [handleCardClick, openCardContextMenu])

    return (
        <CardDragContainer
            cardId={card.header.id}
            cardPath={card.path}
            interactions={dragInteractions}
            isBodyOpen={isBodyOpen}
            isMobile={props.isMobile}
            isSelected={isSelected}
            onCardElementChange={setCardElement}
        >
            <Box sx={{ bgcolor: accentColor, bottom: 0, left: 0, position: 'absolute', top: 0, width: 4 }} />
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, minWidth: 0, p: '10px 12px 10px 14px', pointerEvents: 'none' }}>
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minHeight: 24, position: 'relative', zIndex: 2 }}>
                    <Box
                        component="span"
                        sx={{
                            bgcolor: accentBackground,
                            borderRadius: '5px',
                            color: accentColor,
                            fontFamily: '"Roboto Mono", ui-monospace, monospace',
                            fontSize: 11.5,
                            fontWeight: 600,
                            px: 0.875,
                            py: 0.25,
                        }}
                    >
                        {card.header.id}
                    </Box>
                    <Box component="span" sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', fontSize: 11, gap: 0.625 }}>
                        <Box sx={{ bgcolor: runningRun ? 'success.main' : 'text.disabled', borderRadius: '50%', height: 7, width: 7 }} />
                        {statusLabel}
                    </Box>
                    <Box sx={{ flex: 1 }} />
                    <Tooltip title="Card actions">
                        <IconButton
                            aria-label={`Card actions for ${card.header.id}`}
                            onClick={openCardActions}
                            size="small"
                            sx={{ color: 'text.disabled', height: 24, pointerEvents: 'auto', width: 24 }}
                        >
                            <DotsVertical sx={{ fontSize: 16 }} />
                        </IconButton>
                    </Tooltip>
                </Stack>
                {isEditingTitle ? (
                    <Box sx={{ pointerEvents: 'auto', position: 'relative', zIndex: 2 }}>
                        <TextField
                            autoFocus
                            fullWidth
                            onBlur={commitTitle}
                            onChange={handleTitleDraftChange}
                            onClick={stopClick}
                            onKeyDown={handleTitleKeyDown}
                            size="small"
                            value={titleDraft}
                        />
                    </Box>
                ) : (
                    <Typography sx={{ color: 'text.primary', fontSize: 13.5, fontWeight: 500, lineHeight: 1.4 }}>
                        {card.header.title}
                    </Typography>
                )}
                <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center', minHeight: 26, position: 'relative', zIndex: 2 }}>
                    <Box sx={{ pointerEvents: 'auto' }}>
                        <CardRunButton
                            card={card}
                            context={context}
                        />
                    </Box>
                    <Tooltip title="Open in file mode">
                        <IconButton
                            aria-label={`Open ${card.header.id} in file mode`}
                            onClick={openInFileMode}
                            size="small"
                            sx={{ border: 1, borderColor: 'divider', borderRadius: '50%', height: 26, pointerEvents: 'auto', width: 26 }}
                        >
                            <FileDocumentOutline sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Box sx={{ flex: 1 }} />
                    <CardWorktreeIndicator
                        cardId={card.header.id}
                        cardPath={card.path}
                        primaryPath={primaryPath}
                    />
                </Stack>
            </Box>
            <Menu
                anchorEl={actionsAnchorElement}
                anchorPosition={actionsMenuPosition ?? undefined}
                anchorReference={actionsMenuPosition ? 'anchorPosition' : 'anchorEl'}
                onClose={closeCardActions}
                open={!!actionsAnchorElement || !!actionsMenuPosition}
            >
                <ActionEntryPoints
                    context={context}
                    onMenuItemSelected={closeCardActions}
                    popupAnchorElement={cardElement}
                    variant="menuItems"
                />
                {policyKeys.map((policyKey) => (
                    <CardPolicyMenuItem
                        key={policyKey}
                        cardPath={card.path}
                        enabled={card.header.policy[policyKey] ?? false}
                        onSelected={closeCardActions}
                        onToggle={onTogglePolicy}
                        policyKey={policyKey}
                    />
                ))}
                <CardPathMenuItems cardPath={card.path} onSelected={closeCardActions} rootPath={rootPath} />
                <MenuItem onClick={openBodyFromMenu}>Open body</MenuItem>
                <MenuItem onClick={openInFileModeFromMenu}>Open in file mode</MenuItem>
                <MenuItem onClick={editTitleFromMenu}>Edit title</MenuItem>
                <MenuItem onClick={openDeleteCardDialog}>Delete</MenuItem>
            </Menu>
            <CardDeleteDialog cardPath={deleteCardPath} onClose={closeDeleteCardDialog} onDeleteCard={onDeleteCard} />
        </CardDragContainer>
    )
}

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnEndDropTarget } from './card_column_end_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { CardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
    const handleAddCard = () => {
        requestOpenNewCardDialog(column.status)
    }
    const dropPlaceholder = (
        <Box
            aria-label="Card drop position"
            key="drop-preview"
            sx={{
                bgcolor: 'action.selected',
                border: '1.5px dashed',
                borderColor: 'primary.main',
                borderRadius: 1.25,
                minHeight: dropPreviewHeight ?? 107,
            }}
        />
    )
    const cardElements: ReactNode[] = []
    for (let index = 0; index <= cardPaths.length; index += 1) {
        if (dropPreviewIndex === index) cardElements.push(dropPlaceholder)
        const cardPath = cardPaths[index]
        if (!cardPath) continue

        cardElements.push(
            <CardView
                key={cardPath}
                cardPath={cardPath}
                cardTypes={cardTypes}
                isMobile={isMobile}
                {...handlers}
            />,
        )
    }

    return (
        <Paper
            aria-label={`${columnLabel} column`}
            sx={{
                bgcolor: 'action.hover',
                borderRadius: 1.5,
                display: 'flex',
                flex: isMobile ? '0 0 auto' : 1,
                flexDirection: 'column',
                gap: 1,
                maxWidth: isMobile ? '100%' : MAX_COLUMN_WIDTH,
                minWidth: isMobile ? '100%' : MIN_COLUMN_WIDTH,
                p: 1,
            }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minHeight: 34, pl: 1, pr: 0.5 }}>
                <Box sx={{ bgcolor: column.color, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                <Typography
                    component="h2"
                    sx={{ color: 'text.secondary', fontSize: 12, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {columnLabel}
                </Typography>
                <Chip
                    label={cardPaths.length}
                    size="small"
                    sx={{ bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11, height: 20 }}
                />
                <Box sx={{ flex: 1 }} />
                <Tooltip title="New card">
                    <IconButton aria-label={`Add card from ${columnLabel} column`} onClick={handleAddCard} size="small" sx={{ height: 26, width: 26 }}>
                        <Plus sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>
            <SortableContext items={cardPaths} strategy={verticalListSortingStrategy}>
                {cardElements}
                {cardPaths.length === 0 && dropPreviewIndex === null ? (
                    <Box
                        sx={{
                            border: '1.5px dashed',
                            borderColor: 'divider',
                            borderRadius: 1.25,
                            color: 'text.disabled',
                            fontSize: 12,
                            p: 2,
                            textAlign: 'center',
                        }}
                    >
                        Drop a card here
                    </Box>
                ) : null}
                <CardColumnEndDropTarget status={column.status} />
            </SortableContext>
        </Paper>
    )
}

