            this.actionRunCallbacks.set(result.subscriptionId, callback)
            if (!recover) return
            const events = await this.loadActiveActionRunEvents()
            for (const event of events) callback(event)
        } finally {
            this.requestActionRunEvents.delete(id)
        }
    }

